std::accumulate(
      layers.begin(), layers.end(), box,
      [](Box acc, int layer) {
        auto &bucket = acc.bucket;
        if (layer % 2 == 0)
          ++bucket.hits;
        else
          bucket.misses += 1;
        return acc;
      })

